package com.amit.jobagent.application;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;import org.hibernate.annotations.JdbcTypeCode;import org.hibernate.type.SqlTypes;
@Entity @Table(name="document_artifact")class DocumentArtifact{@Id UUID id;@Column(name="package_revision_id",nullable=false,updatable=false)UUID revisionId;@Enumerated(EnumType.STRING)@Column(name="artifact_type",nullable=false,updatable=false,length=30)ArtifactType type;@Column(name="storage_bucket",nullable=false,updatable=false,length=100)String bucket;@Column(name="storage_key",nullable=false,unique=true,updatable=false,length=700)String storageKey;@Column(name="file_name",nullable=false,updatable=false,length=255)String fileName;@Column(name="content_type",nullable=false,updatable=false,length=150)String contentType;@Column(name="size_bytes",nullable=false,updatable=false)long size;@JdbcTypeCode(SqlTypes.CHAR)@Column(name="sha256_checksum",nullable=false,updatable=false,length=64,columnDefinition="char(64)")String checksum;@Column(name="template_version",nullable=false,updatable=false,length=40)String templateVersion;@Column(name="rendering_status",nullable=false,updatable=false,length=30)String renderingStatus;@Column(name="created_at",nullable=false,updatable=false)Instant createdAt;protected DocumentArtifact(){}DocumentArtifact(UUID revision,ArtifactType type,String bucket,String key,String file,String mime,long size,String hash,String template){id=UUID.randomUUID();revisionId=revision;this.type=type;this.bucket=bucket;storageKey=key;fileName=file;contentType=mime;this.size=size;checksum=hash;templateVersion=template;renderingStatus="READY";createdAt=Instant.now();}}
